      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

# The deployment harness injects the AWS provider configuration
# (region = "us-east-1"). Declaring it here as well would create a
# duplicate provider block, so it is left out on purpose.

variable "environment" {
  description = "Deployment environment name applied to resource tags."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Project   = "cloudwatch-logging"
    ManagedBy = "terraform"
  }
}

locals {
  log_group_prefix   = "log-group-"
  log_retention_days = 30

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

resource "random_pet" "log_group_suffix" {
  length    = 2
  separator = "-"
}

resource "aws_cloudwatch_log_group" "app_logs" {
  name              = "${local.log_group_prefix}${random_pet.log_group_suffix.id}"
  retention_in_days = local.log_retention_days

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

output "log_group_name" {
  description = "Name of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.app_logs.name
}

output "log_group_arn" {
  description = "ARN of the CloudWatch log group."
  value       = aws_cloudwatch_log_group.app_logs.arn
}

