terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "bucket_name" {
  description = "Name of the S3 bucket used for benchmarking."
  type        = string
  default     = "benchmark-bucket-tf5x"
}

variable "name_tag" {
  description = "Value of the Name tag applied to the S3 bucket."
  type        = string
  default     = "benchmark"
}

variable "force_destroy" {
  description = "Allow terraform destroy to delete the bucket even when it still contains objects."
  type        = bool
  default     = true
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

data "aws_region" "current" {}

locals {
  account_id     = data.aws_caller_identity.current.account_id
  partition      = data.aws_partition.current.partition
  region         = data.aws_region.current.name
  root_principal = "arn:${local.partition}:iam::${local.account_id}:root"
  s3_via_service = "s3.${local.region}.amazonaws.com"
  kms_alias_name = "alias/${var.bucket_name}-key"
}

resource "aws_kms_key" "s3_bucket_key" {
  description              = "Customer-managed KMS key for SSE-KMS encryption of S3 bucket ${var.bucket_name}"
  key_usage                = "ENCRYPT_DECRYPT"
  customer_master_key_spec = "SYMMETRIC_DEFAULT"
  enable_key_rotation      = true
  deletion_window_in_days  = 7
  is_enabled               = true

  policy = jsonencode({
    Version = "2012-10-17"
    Id      = "s3-bucket-key-policy"
    Statement = [
      {
        Sid    = "EnableRootAccountKeyAdministration"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowS3UseOfTheKeyForThisAccount"
        Effect = "Allow"
        Principal = {
          AWS = local.root_principal
        }
        Action = [
          "kms:Encrypt",
          "kms:Decrypt",
          "kms:ReEncrypt*",
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "kms:ViaService"    = local.s3_via_service
            "kms:CallerAccount" = local.account_id
          }
        }
      }
    ]
  })

  tags = {
    Name = "${var.name_tag}-s3-kms-key"
  }
}

resource "aws_kms_alias" "s3_bucket_key" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.s3_bucket_key.key_id
}

resource "aws_s3_bucket" "benchmark" {
  bucket        = var.bucket_name
  force_destroy = var.force_destroy

  tags = {
    Name = var.name_tag
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.s3_bucket_key.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_account_public_access_block" "account" {
  block_public_acls   = false
  block_public_policy = false
}

resource "aws_s3_bucket_public_access_block" "benchmark" {
  bucket = aws_s3_bucket.benchmark.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true

  depends_on = [aws_s3_account_public_access_block.account]
}

output "bucket_name" {
  description = "Name of the benchmark S3 bucket."
  value       = aws_s3_bucket.benchmark.id
}

output "bucket_arn" {
  description = "ARN of the benchmark S3 bucket."
  value       = aws_s3_bucket.benchmark.arn
}

output "kms_key_arn" {
  description = "ARN of the customer-managed KMS key used for bucket encryption."
  value       = aws_kms_key.s3_bucket_key.arn
}

output "kms_key_alias" {
  description = "Alias of the customer-managed KMS key."
  value       = aws_kms_alias.s3_bucket_key.name
}

output "account_public_access_block_id" {
  description = "Account ID that the account-level S3 public access block applies to."
  value       = aws_s3_account_public_access_block.account.id
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

data "aws_region" "current" {}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

variable "base_name" {
  description = "Prefix for the CloudTrail log bucket name."
  type        = string
  default     = "benchmark"
}

locals {
  bucket_name           = "${var.base_name}-cloudtrail-${data.aws_region.current.name}"
  account_id            = data.aws_caller_identity.current.account_id
  cloudtrail_principal  = "cloudtrail.amazonaws.com"
  account_root_arn      = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"
  cloudtrail_source_arn = "arn:${data.aws_partition.current.partition}:cloudtrail:${data.aws_region.current.name}:${data.aws_caller_identity.current.account_id}:trail/*"

  common_tags = {
    Name    = local.bucket_name
    Purpose = "cloudtrail-logs"
  }
}

resource "aws_kms_key" "cloudtrail" {
  description             = "Customer-managed KMS key for ${local.bucket_name} CloudTrail log bucket"
  key_usage               = "ENCRYPT_DECRYPT"
  deletion_window_in_days = 30
  enable_key_rotation     = true

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "EnableAccountRootPermissions"
        Effect = "Allow"
        Principal = {
          AWS = local.account_root_arn
        }
        Action   = "kms:*"
        Resource = "*"
      },
      {
        Sid    = "AllowCloudTrailToUseKey"
        Effect = "Allow"
        Principal = {
          Service = local.cloudtrail_principal
        }
        Action = [
          "kms:GenerateDataKey*",
          "kms:DescribeKey"
        ]
        Resource = "*"
        Condition = {
          StringEquals = {
            "aws:SourceAccount" = local.account_id
          }
          StringLike = {
            "kms:EncryptionContext:aws:cloudtrail:arn" = local.cloudtrail_source_arn
          }
        }
      }
    ]
  })

  tags = local.common_tags
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/${local.bucket_name}"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

resource "aws_s3_bucket" "cloudtrail_logs" {
  bucket        = local.bucket_name
  force_destroy = true

  tags = local.common_tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_s3_bucket_public_access_block" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id

  versioning_configuration {
    status = "Enabled"
  }
}

data "aws_iam_policy_document" "cloudtrail_logs" {
  statement {
    sid     = "AWSCloudTrailAclCheck"
    effect  = "Allow"
    actions = ["s3:GetBucketAcl"]

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_principal]
    }

    resources = [aws_s3_bucket.cloudtrail_logs.arn]

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }

  statement {
    sid     = "AWSCloudTrailWrite"
    effect  = "Allow"
    actions = ["s3:PutObject"]

    principals {
      type        = "Service"
      identifiers = [local.cloudtrail_principal]
    }

    resources = ["${aws_s3_bucket.cloudtrail_logs.arn}/*"]

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }

    condition {
      test     = "StringEquals"
      variable = "aws:SourceAccount"
      values   = [local.account_id]
    }
  }
}

resource "aws_s3_bucket_policy" "cloudtrail_logs" {
  bucket = aws_s3_bucket.cloudtrail_logs.id
  policy = data.aws_iam_policy_document.cloudtrail_logs.json

  depends_on = [aws_s3_bucket_public_access_block.cloudtrail_logs]
}

output "cloudtrail_bucket_name" {
  description = "Name of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail_logs.id
}

output "cloudtrail_bucket_arn" {
  description = "ARN of the CloudTrail log bucket."
  value       = aws_s3_bucket.cloudtrail_logs.arn
}

output "cloudtrail_kms_key_arn" {
  description = "ARN of the customer-managed KMS key used to encrypt CloudTrail logs."
  value       = aws_kms_key.cloudtrail.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"

  default_tags {
    tags = {
      App    = var.app
      Module = var.module
      Stage  = var.stage
    }
  }
}

variable "app_name" {
  description = "Human-readable application name."
  type        = string
  default     = "Trilium Notes"
}

variable "app" {
  description = "Short application identifier used in resource names."
  type        = string
  default     = "trilium"
}

variable "module" {
  description = "Module or component identifier."
  type        = string
  default     = "log"
}

variable "stage" {
  description = "Deployment stage or environment."
  type        = string
  default     = "production"
}

variable "log_retention" {
  description = "CloudWatch log retention in days."
  type        = number
  default     = 120

  validation {
    condition = contains(
      [0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653],
      var.log_retention
    )
    error_message = "log_retention must be one of: 0, 1, 3, 5, 7, 14, 30, 60, 90, 120, 150, 180, 365, 400, 545, 731, 1096, 1827, 2192, 2557, 2922, 3288, 3653."
  }
}

locals {
  name_prefix    = "cwlg-${var.app}-${var.module}-${var.stage}"
  app_log_name   = "${local.name_prefix}-app"
  proxy_log_name = "${local.name_prefix}-proxy"
}

resource "aws_cloudwatch_log_group" "app" {
  name              = local.app_log_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.app_log_name
  }
}

resource "aws_cloudwatch_log_group" "proxy" {
  name              = local.proxy_log_name
  retention_in_days = var.log_retention

  tags = {
    Name = local.proxy_log_name
  }
}

output "app_log_group_name" {
  description = "Name of the application CloudWatch log group."
  value       = aws_cloudwatch_log_group.app.name
}

output "app_log_group_arn" {
  description = "ARN of the application CloudWatch log group."
  value       = aws_cloudwatch_log_group.app.arn
}

output "proxy_log_group_name" {
  description = "Name of the reverse proxy CloudWatch log group."
  value       = aws_cloudwatch_log_group.proxy.name
}

output "proxy_log_group_arn" {
  description = "ARN of the reverse proxy CloudWatch log group."
  value       = aws_cloudwatch_log_group.proxy.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Environment name used for tagging resources."
  type        = string
  default     = "test"
}

variable "tags" {
  description = "Common tags applied to all taggable resources."
  type        = map(string)
  default = {
    Project   = "cloudrail-test"
    ManagedBy = "terraform"
  }
}

data "aws_caller_identity" "current" {}

data "aws_partition" "current" {}

locals {
  name_prefix          = "cloudrail-test"
  efs_creation_token   = "cloudrail-test"
  task_family          = "cloudrail-test-encryption"
  efs_volume_name      = "service-storage"
  efs_root_directory   = "/opt/data"
  efs_transit_port     = 2999
  kms_alias_name       = "alias/cloudrail-test-efs"
  account_root_arn     = "arn:${data.aws_partition.current.partition}:iam::${data.aws_caller_identity.current.account_id}:root"

  common_tags = merge(
    var.tags,
    {
      Environment = var.environment
    }
  )
}

data "aws_iam_policy_document" "efs_kms" {
  statement {
    sid    = "EnableRootAccountAdministration"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = [local.account_root_arn]
    }

    actions = [
      "kms:Create*",
      "kms:Describe*",
      "kms:Enable*",
      "kms:List*",
      "kms:Put*",
      "kms:Update*",
      "kms:Revoke*",
      "kms:Disable*",
      "kms:Get*",
      "kms:Delete*",
      "kms:TagResource",
      "kms:UntagResource",
      "kms:ScheduleKeyDeletion",
      "kms:CancelKeyDeletion",
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant"
    ]

    resources = ["*"]
  }

  statement {
    sid    = "AllowEFSServiceUseViaAccount"
    effect = "Allow"

    principals {
      type        = "AWS"
      identifiers = ["*"]
    }

    actions = [
      "kms:Encrypt",
      "kms:Decrypt",
      "kms:ReEncrypt*",
      "kms:GenerateDataKey*",
      "kms:CreateGrant",
      "kms:DescribeKey"
    ]

    resources = ["*"]

    condition {
      test     = "StringEquals"
      variable = "kms:CallerAccount"
      values   = [data.aws_caller_identity.current.account_id]
    }

    condition {
      test     = "StringEquals"
      variable = "kms:ViaService"
      values   = ["elasticfilesystem.us-east-1.amazonaws.com"]
    }
  }
}

resource "aws_kms_key" "efs" {
  description             = "KMS key for encrypting the ${local.name_prefix} EFS file system"
  deletion_window_in_days = 30
  enable_key_rotation     = true
  policy                  = data.aws_iam_policy_document.efs_kms.json

  tags = merge(
    local.common_tags,
    {
      Name = "${local.name_prefix}-efs-kms"
    }
  )
}

resource "aws_kms_alias" "efs" {
  name          = local.kms_alias_name
  target_key_id = aws_kms_key.efs.key_id
}

resource "aws_efs_file_system" "cloudrail_test" {
  creation_token   = local.efs_creation_token
  encrypted        = true
  kms_key_id       = aws_kms_key.efs.arn
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  lifecycle_policy {
    transition_to_ia = "AFTER_30_DAYS"
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.name_prefix
    }
  )

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecs_task_definition" "cloudrail_test_encryption" {
  family                   = local.task_family
  network_mode             = "bridge"
  requires_compatibilities = ["EC2"]

  container_definitions = jsonencode([
    {
      name      = "first"
      image     = "service-first"
      cpu       = 10
      memory    = 512
      essential = true
      portMappings = [
        {
          containerPort = 80
          hostPort      = 80
          protocol      = "tcp"
        }
      ]
    },
    {
      name      = "second"
      image     = "service-second"
      cpu       = 10
      memory    = 256
      essential = true
      portMappings = [
        {
          containerPort = 443
          hostPort      = 443
          protocol      = "tcp"
        }
      ]
    }
  ])

  volume {
    name = local.efs_volume_name

    efs_volume_configuration {
      file_system_id          = aws_efs_file_system.cloudrail_test.id
      root_directory          = local.efs_root_directory
      transit_encryption      = "ENABLED"
      transit_encryption_port = local.efs_transit_port
    }
  }

  tags = merge(
    local.common_tags,
    {
      Name = local.task_family
    }
  )
}

output "efs_file_system_id" {
  description = "ID of the encrypted EFS file system."
  value       = aws_efs_file_system.cloudrail_test.id
}

output "efs_file_system_arn" {
  description = "ARN of the encrypted EFS file system."
  value       = aws_efs_file_system.cloudrail_test.arn
}

output "ecs_task_definition_arn" {
