# Region is us-east-1. The deployment harness injects the AWS provider block, so this file does not declare one.

terraform {
  required_version = ">= 1.3.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
    tls = {
      source  = "hashicorp/tls"
      version = "~> 4.0"
    }
    random = {
      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

variable "key_prefix" {
  description = "Prefix for the generated key pair name"
  type        = string
  default     = "key"
}

resource "random_pet" "key_suffix" {
  length    = 2
  separator = "-"
}

locals {
  key_name         = "${var.key_prefix}-${random_pet.key_suffix.id}"
  private_key_file = "../${local.key_name}.pem"
}

# The private key is also stored unencrypted in Terraform state.
# Keep state in a secure, encrypted backend that is managed outside this configuration.
resource "tls_private_key" "ssh" {
  algorithm = "RSA"
  rsa_bits  = 4096
}

resource "aws_key_pair" "ssh" {
  key_name   = local.key_name
  public_key = tls_private_key.ssh.public_key_openssh

  tags = {
    Name      = local.key_name
    ManagedBy = "terraform"
  }

  provisioner "local-exec" {
    command = "umask 077 && printf '%s\\n' \"$PRIVATE_KEY\" > \"$KEY_FILE\" && chmod 600 \"$KEY_FILE\""

    environment = {
      PRIVATE_KEY = tls_private_key.ssh.private_key_pem
      KEY_FILE    = local.private_key_file
    }
  }

  provisioner "local-exec" {
    when    = destroy
    command = "rm -f \"../${self.key_name}.pem\""
  }
}

output "key_pair_name" {
  description = "Name of the AWS key pair"
  value       = aws_key_pair.ssh.key_name
}

output "private_key_file" {
  description = "Path to the local PEM file that holds the private key"
  value       = local.private_key_file
}

output "private_key_pem" {
  description = "Generated private key in PEM format"
  value       = tls_private_key.ssh.private_key_pem
  sensitive   = true
}

terraform {
  required_version = ">= 1.5.0"

  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "environment" {
  description = "Deployment environment name used in resource naming and tagging."
  type        = string
  default     = "dev"
}

variable "tags" {
  description = "Common tags applied to all resources."
  type        = map(string)
  default = {
    Project   = "web-services"
    ManagedBy = "terraform"
  }
}

locals {
  vpc_name      = "${var.environment}-web-vpc"
  sg_name_tag   = "${var.environment}-web-sg"
  anywhere_ipv4 = "0.0.0.0/0"
  tcp_protocol  = "tcp"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = merge(var.tags, {
    Name = local.vpc_name
  })
}

resource "aws_security_group" "example" {
  name        = "Example security group"
  description = "Allows inbound HTTP and HTTPS web traffic"
  vpc_id      = aws_vpc.main.id

  tags = merge(var.tags, {
    Name = local.sg_name_tag
  })
}

# Public ingress (0.0.0.0/0) is permitted only on ports 80 and 443 because
# these are public web service ports. No other inbound port is opened.
resource "aws_vpc_security_group_ingress_rule" "https" {
  security_group_id = aws_security_group.example.id
  description       = "Allow HTTPS from anywhere"
  ip_protocol       = local.tcp_protocol
  from_port         = 443
  to_port           = 443
  cidr_ipv4         = local.anywhere_ipv4

  tags = var.tags
}

resource "aws_vpc_security_group_ingress_rule" "http" {
  security_group_id = aws_security_group.example.id
  description       = "Allow HTTP from anywhere"
  ip_protocol       = local.tcp_protocol
  from_port         = 80
  to_port           = 80
  cidr_ipv4         = local.anywhere_ipv4

  tags = var.tags
}

# Outbound internet access is intentionally not opened on this security group
# to satisfy AVD-AWS-0104 (no unrestricted egress). Egress is limited to the
# VPC's own address space (other tiers, VPC endpoints, the AWS DNS resolver).
# If internet egress is required later, provide it through a controlled path
# such as a NAT gateway or egress proxy with specific destination CIDRs rather
# than 0.0.0.0/0 on this security group.
resource "aws_vpc_security_group_egress_rule" "vpc_internal" {
  security_group_id = aws_security_group.example.id
  description       = "Allow outbound traffic within the VPC"
  ip_protocol       = "-1"
  cidr_ipv4         = aws_vpc.main.cidr_block

  tags = var.tags
}

output "vpc_id" {
  description = "ID of the web services VPC."
  value       = aws_vpc.main.id
}

output "security_group_id" {
  description = "ID of the Example security group."
  value       = aws_security_group.example.id
}

