variable "repository_name" {
  description = "Name of the ECR repository."
  type        = string
  default     = "illumidesk"
}

variable "tags" {
  description = "Map of tags applied to all taggable resources."
  type        = map(string)
  default = {
    Name        = "illumidesk-eks"
    Environment = "dev"
  }
}

locals {
  lifecycle_action_type = "expire"
}

resource "aws_ecr_repository" "illumidesk" {
  name                 = var.repository_name
  image_tag_mutability = "IMMUTABLE"
  force_delete         = false

  image_scanning_configuration {
    scan_on_push = true
  }

  encryption_configuration {
    encryption_type = "AES256"
  }

  tags = var.tags

  lifecycle {
    prevent_destroy = true
  }
}

resource "aws_ecr_lifecycle_policy" "illumidesk" {
  repository = aws_ecr_repository.illumidesk.name

  policy = jsonencode({
    rules = [
      {
        rulePriority = 1
        description  = "Expire untagged images older than 14 days"
        selection = {
          tagStatus   = "untagged"
          countType   = "sinceImagePushed"
          countUnit   = "days"
          countNumber = 14
        }
        action = {
          type = local.lifecycle_action_type
        }
      },
      {
        rulePriority = 2
        description  = "Keep last 30 images"
        selection = {
          tagStatus   = "any"
          countType   = "imageCountMoreThan"
          countNumber = 30
        }
        action = {
          type = local.lifecycle_action_type
        }
      }
    ]
  })
}

output "repository_url" {
  description = "URL of the ECR repository."
  value       = aws_ecr_repository.illumidesk.repository_url
}

output "repository_arn" {
  description = "ARN of the ECR repository."
  value       = aws_ecr_repository.illumidesk.arn
}

output "repository_name" {
  description = "Name of the ECR repository."
  value       = aws_ecr_repository.illumidesk.name
}

