      source  = "hashicorp/random"
      version = "~> 3.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

variable "region" {
  description = "AWS region value stored inside the secret payload"
  type        = string
  default     = "us-east-1"
}

variable "secret_name" {
  description = "Name of the Secrets Manager secret holding the Lambda auth credentials"
  type        = string
  default     = "lambda-auth-credentials"
}

variable "default_username" {
  description = "Default username stored in the secret payload"
  type        = string
  default     = "techlanches"
}

variable "default_email" {
  description = "Default email stored in the secret payload"
  type        = string
  default     = "g12.4soat.fiap@outlook.com"
}

locals {
  user_pool_name   = "tech-lanches-clientes-pool"
  user_pool_tag    = "tech_lanches_clientes_pool"
  pool_client_name = "pool-client"
}

resource "random_password" "default_user" {
  length           = 16
  special          = true
  override_special = "!@#$%&*"
  min_upper        = 1
  min_lower        = 1
  min_numeric      = 1
  min_special      = 1
}

resource "aws_cognito_user_pool" "clientes_pool" {
  name              = local.user_pool_name
  mfa_configuration = "OFF"

  username_configuration {
    case_sensitive = false
  }

  auto_verified_attributes = ["email"]
  alias_attributes         = ["email", "preferred_username"]

  tags = {
    Name = local.user_pool_tag
  }
}

resource "aws_cognito_user_pool_client" "pool_client" {
  name         = local.pool_client_name
  user_pool_id = aws_cognito_user_pool.clientes_pool.id

  generate_secret = false

  explicit_auth_flows = [
    "ALLOW_REFRESH_TOKEN_AUTH",
    "ALLOW_USER_SRP_AUTH",
    "ALLOW_ADMIN_USER_PASSWORD_AUTH",
  ]
}

resource "aws_secretsmanager_secret" "lambda_auth_credentials" {
  name                    = var.secret_name
  description             = "Cognito credentials used by the authentication Lambda"
  recovery_window_in_days = 0
}

resource "aws_secretsmanager_secret_version" "lambda_auth_credentials" {
  secret_id = aws_secretsmanager_secret.lambda_auth_credentials.id

  secret_string = jsonencode({
    region       = var.region
    user_pool_id = aws_cognito_user_pool.clientes_pool.id
    client_id    = aws_cognito_user_pool_client.pool_client.id
    username     = var.default_username
    email        = var.default_email
    password     = random_password.default_user.result
  })
}

output "user_pool_id" {
  description = "ID of the Cognito User Pool"
  value       = aws_cognito_user_pool.clientes_pool.id
}

output "user_pool_client_id" {
  description = "ID of the Cognito User Pool Client"
  value       = aws_cognito_user_pool_client.pool_client.id
}

output "secret_arn" {
  description = "ARN of the Secrets Manager secret holding the Lambda auth credentials"
  value       = aws_secretsmanager_secret.lambda_auth_credentials.arn
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

# The deployment harness injects the AWS provider configuration, so this file
# has no provider block. Pass this variable to that injected provider as
# region = var.aws_region. It defaults to "us-east-1" unless overridden.
variable "aws_region" {
  description = "AWS region to deploy the networking stack into."
  type        = string
  default     = "us-east-1"

  validation {
    condition     = can(regex("^[a-z]{2}(-[a-z]+)+-[0-9]+$", var.aws_region))
    error_message = "The aws_region value must be a valid AWS region name, e.g. \"us-east-1\"."
  }
}

variable "vpc_cidr" {
  description = "CIDR block for the main VPC."
  type        = string
  default     = "10.0.0.0/16"

  validation {
    condition     = can(cidrhost(var.vpc_cidr, 0))
    error_message = "The vpc_cidr value must be a valid IPv4 CIDR block, e.g. \"10.0.0.0/16\"."
  }
}

variable "subnet_cidrs" {
  description = "CIDR blocks for the subnets. One subnet is created per entry."
  type        = list(string)
  default     = ["10.0.1.0/24", "10.0.2.0/24"]

  validation {
    condition     = length(var.subnet_cidrs) > 0 && alltrue([for cidr in var.subnet_cidrs : can(cidrhost(cidr, 0))])
    error_message = "The subnet_cidrs value must contain at least one entry, and every entry must be a valid IPv4 CIDR block."
  }
}

variable "availability_zones" {
  description = "Availability zones for the subnets, matched to subnet_cidrs by index. An empty list uses the first N available AZs in the region."
  type        = list(string)
  default     = []
}

data "aws_availability_zones" "available" {
  state = "available"
}

locals {
  vpc_name           = "main-vpc"
  subnet_name_prefix = "main-subnet"

  # min() stops slice() from failing when the region has fewer AZs than
  # subnets. The precondition on aws_subnet.main reports that case clearly.
  azs = length(var.availability_zones) > 0 ? var.availability_zones : slice(
    data.aws_availability_zones.available.names,
    0,
    min(length(var.subnet_cidrs), length(data.aws_availability_zones.available.names))
  )
}

resource "aws_vpc" "main" {
  cidr_block           = var.vpc_cidr
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = local.vpc_name
  }
}

resource "aws_subnet" "main" {
  count = length(var.subnet_cidrs)

  vpc_id                  = aws_vpc.main.id
  cidr_block              = var.subnet_cidrs[count.index]
  availability_zone       = local.azs[count.index]
  map_public_ip_on_launch = false

  tags = {
    Name = "${local.subnet_name_prefix}-${count.index + 1}"
  }

  lifecycle {
    precondition {
      condition     = length(local.azs) >= length(var.subnet_cidrs)
      error_message = "There are fewer availability zones than subnet CIDR blocks. Provide at least as many entries in availability_zones as in subnet_cidrs, or use a region with enough available AZs."
    }
  }
}

output "vpc_id" {
  description = "ID of the main VPC."
  value       = aws_vpc.main.id
}

output "vpc_cidr_block" {
  description = "CIDR block of the main VPC."
  value       = aws_vpc.main.cidr_block
}

output "subnet_ids" {
  description = "IDs of the subnets, in the same order as subnet_cidrs."
  value       = aws_subnet.main[*].id
}

output "subnet_availability_zones" {
  description = "Availability zone of each subnet, in the same order as subnet_ids."
  value       = aws_subnet.main[*].availability_zone
}

terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

